<?php
// Run inside WordPress: wp eval-file tools/check-chat-knowledge-pack-v2.php
if ( ! defined( 'ABSPATH' ) ) { fwrite( STDERR, "Run with wp eval-file.\n" ); exit( 1 ); }
$rows = $wpdb->get_results( "SELECT question, answer, normalized, fingerprint, lang, intent FROM " . BHC_Chat_Knowledge_Store::table() . " WHERE source='pack_v2'", ARRAY_A );
$seen = array(); $bad = array(); $intents = array(); $langs = array(); $max_question_length = 0; $required_intents = array( 'purchase', 'compare', 'budget', 'return', 'warranty', 'payment', 'shipping', 'support', 'order', 'complaint', 'unknown' );
foreach ( $rows as $r ) { $n = BHC_Chat_Knowledge_Store::normalize( $r['question'] ); $fp = hash( 'sha256', $n . '|' . sanitize_key( $r['lang'] ) ); $max_question_length = max( $max_question_length, mb_strlen( $n, 'UTF-8' ) ); if ( isset( $seen[$fp] ) ) $bad['duplicate_fingerprint'] = ( $bad['duplicate_fingerprint'] ?? 0 ) + 1; $seen[$fp] = 1; if ( trim( $r['answer'] ) === '' ) $bad['empty_answer'] = ( $bad['empty_answer'] ?? 0 ) + 1; if ( mb_strlen( $n, 'UTF-8' ) > 190 ) $bad['question_over_190'] = ( $bad['question_over_190'] ?? 0 ) + 1; if ( preg_match( '/(?:تومان|ریال|قیمت\s*[:：]?\s*[0-9۰-۹]|\b[0-9]{4,}\b)/u', $r['answer'] ) ) $bad['numeric_price'] = ( $bad['numeric_price'] ?? 0 ) + 1; if ( preg_match( '/<[^>]+>/u', $r['answer'] ) ) $bad['html_answer'] = ( $bad['html_answer'] ?? 0 ) + 1; $intents[$r['intent']] = ( $intents[$r['intent']] ?? 0 ) + 1; $langs[$r['lang']] = ( $langs[$r['lang']] ?? 0 ) + 1; }
$missing_intents = array_values( array_diff( $required_intents, array_keys( $intents ) ) );
echo wp_json_encode( array( 'rows' => count( $rows ), 'unique_fingerprints' => count( $seen ), 'max_normalized_question_length' => $max_question_length, 'missing_intents' => $missing_intents, 'bad' => $bad, 'intents' => $intents, 'langs' => $langs, 'sample_partial' => array_slice( array_column( $rows, 'question' ), 0, 20 ) ), JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT ) . "\n";
